def length_of_lis(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    # dp[i] represents the length of the longest increasing subsequence ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

