def length_of_lis(nums: list[int]) -> int:
    if not nums:
        return 0

    # tails[i] is the smallest tail of all increasing subsequences of length i+1
    tails = []
    for x in nums:
        # Binary search to find the insertion point for x
        low, high = 0, len(tails)
        while low < high:
            mid = (low + high) // 2
            if tails[mid] < x:
                low = mid + 1
            else:
                high = mid

        if low == len(tails):
            tails.append(x)
        else:
            tails[low] = x

    return len(tails)

